import java.util.concurrent.ConcurrentHashMap;

public class TokenBucketLimiter {
    private static class Bucket {
        double tokens;
        long lastRefillMs;
        Bucket(double tokens, long now) { this.tokens = tokens; this.lastRefillMs = now; }
    }
    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();
    private final double capacity;   // max burst
    private final double refillPerMs; // sustained rate

    public TokenBucketLimiter(double permitsPerSecond, double maxBurst) {
        this.capacity = maxBurst;
        this.refillPerMs = permitsPerSecond / 1000.0;
    }

    public boolean allow(String key) {
        return allow(key, 1);
    }

    public boolean allow(String key, int cost) {
        long now = System.currentTimeMillis();
        Bucket b = buckets.computeIfAbsent(key, k -> new Bucket(capacity, now));
        synchronized (b) {
            // lazy refill: no background thread, O(1) per request
            long elapsed = now - b.lastRefillMs;
            if (elapsed > 0) {
                b.tokens = Math.min(capacity, b.tokens + elapsed * refillPerMs);
                b.lastRefillMs = now;
            }
            if (b.tokens >= cost) {
                b.tokens -= cost;
                return true;
            }
            return false;
        }
    }

    // Lua equivalent for Redis (atomic across gateways):
    // KEYS[1]=bucket key, ARGV[1]=capacity, ARGV[2]=refill_per_ms,
    // ARGV[3]=now_ms, ARGV[4]=cost
    static final String LUA =
        "local b = redis.call('HMGET', KEYS[1], 'tokens', 'ts') " +
        "local tokens = tonumber(b[1]) or tonumber(ARGV[1]) " +
        "local ts = tonumber(b[2]) or tonumber(ARGV[3]) " +
        "local elapsed = math.max(0, tonumber(ARGV[3]) - ts) " +
        "tokens = math.min(tonumber(ARGV[1]), tokens + elapsed * tonumber(ARGV[2])) " +
        "if tokens >= tonumber(ARGV[4]) then " +
        "  redis.call('HMSET', KEYS[1], 'tokens', tokens - tonumber(ARGV[4]), 'ts', ARGV[3]) " +
        "  redis.call('PEXPIRE', KEYS[1], 60000) " +
        "  return 1 else " +
        "  redis.call('HMSET', KEYS[1], 'tokens', tokens, 'ts', ARGV[3]) " +
        "  redis.call('PEXPIRE', KEYS[1], 60000) " +
        "  return 0 end";
}

import time

class SlidingWindowCounter:
    """Approximate sliding window: O(1) state, no per-request log.
    Trade-off vs log: ~1-2% over-admit at boundary for 10x less memory."""
    def __init__(self):
        self.windows: dict[str, tuple[int, int]] = {}  # key -> (prev, curr)
        self.window_start: dict[str, float] = {}

    def allow(self, key: str, limit: int, window_sec: int) -> bool:
        now = time.time()
        start = self.window_start.get(key, now)
        prev, curr = self.windows.get(key, (0, 0))
        # roll window if expired
        if now - start >= window_sec:
            if now - start >= 2 * window_sec:
                prev, curr = 0, 0
            else:
                prev, curr = curr, 0
            start = start + window_sec
            self.window_start[key] = start
        elapsed = now - start
        estimate = prev * (1 - elapsed / window_sec) + curr
        if estimate + 1 > limit:
            return False
        self.windows[key] = (prev, curr + 1)
        return True
